sqlQueries.sql:
insert into tags (user_id, slug) values ($1, slugify($2)) on conflict (user_id, slug) do update set slug = excluded.slug returning id;
insert into tag_labels (tag_id, language, label) values ($tag_id, $language, btrim($label)) on conflict (tag_id, language) do nothing;
insert into note_tags (note_id, tag_id, user_id) values ($note_id, $tag_id, $user_id) on conflict (note_id, tag_id) do nothing;

select count(*) >= p_limit from ai_jobs
where user_id = p_user_id and stage = p_stage
  and created_at >= now() - make_interval(mins => p_window_minutes);

with deleted as (
  delete from ai_jobs where created_at < now() - make_interval(days => p_days)
  returning 1
)
select count(*)::integer from deleted;
